import app from 'flarum/forum/app';
import Button from 'flarum/common/components/Button';
import AbstractPoll from './Poll/AbstractPoll';
import PollControls from '../utils/PollControls';
export default class PollView extends AbstractPoll {
  className() {
    return 'Poll';
  }
  controlItems() {
    const poll = this.attrs.poll;
    const items = PollControls.controls(poll, this);
    if (poll.publicPoll() || poll.canEdit()) {
      items.add('voters', m(Button, {
        onclick: this.state.showVoters,
        icon: "fas fa-poll"
      }, app.translator.trans('fof-polls.forum.public_poll')), 100);
    }
    return items;
  }
}
flarum.reg.add('fof-polls', 'forum/components/PollView', PollView);