import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Dropdown from 'flarum/common/components/Dropdown';
import Placeholder from 'flarum/common/components/Placeholder';
import ItemList from 'flarum/common/utils/ItemList';
import PollGroupControls from '../../utils/PollGroupControls';
import PollListItem from '../Poll/PollListItem';
import PollShowcaseItem from '../Poll/PollShowcaseItem';
export default class PollGroupListItem extends Component {
  view() {
    const polls = this.pollItems().toArray();
    return m("div", {
      className: "PollGroupListItem"
    }, m("div", {
      className: "PollGroupListItem-main"
    }, this.mainItems().toArray()), polls.length ? m("ul", {
      className: "PollGroupListItem-polls"
    }, polls) : m(Placeholder, {
      text: app.translator.trans('fof-polls.forum.poll_groups.list_page.no_polls')
    }));
  }
  mainItems() {
    const items = new ItemList();
    items.add('title', m("h3", {
      className: "PollGroupListItem-title"
    }, this.attrs.pollGroup.name()), 100);
    const controls = this.controlsView();
    if (controls) items.add('controls', controls, 0);
    return items;
  }
  pollItems() {
    const items = new ItemList();
    const polls = this.attrs.pollGroup.polls();
    polls?.forEach(poll => {
      if (!poll) return;
      items.add(`poll-${poll.id()}`, m("li", {
        key: poll.id(),
        className: "PollGroupListItem-poll"
      }, this.attrs.compactView ? m(PollListItem, {
        poll: poll
      }) : m(PollShowcaseItem, {
        poll: poll
      })));
    });
    return items;
  }
  controlsView() {
    const controls = PollGroupControls.controls(this.attrs.pollGroup, this).toArray();
    if (!controls.length) return null;
    return m(Dropdown, {
      icon: "fas fa-ellipsis-v",
      className: "PollGroupListItem-controls",
      menuClassName: "Dropdown-menu--right",
      buttonClassName: "Button Button--icon Button--flat",
      accessibleToggleLabel: app.translator.trans('fof-polls.forum.poll_controls.toggle_dropdown_accessible_label')
    }, controls);
  }
}
flarum.reg.add('fof-polls', 'forum/components/PollGroup/PollGroupListItem', PollGroupListItem);